WEST_EDict = {}

FENIX_EDict = {}

MANTA_EDict = {}

#shotNum is a string
def getEdict(shotNum, machine):
    if machine == 'DIIID':
        return DIIID_EDict[shotNum]
    elif machine == 'WEST':
        return WEST_EDict[shotNum]
    elif machine == 'MANTA':
        return MANTA_EDict[shotNum]
    elif machine == 'FENIX':
        return FENIX_EDict[shotNum]
